import numpy as np,json
D=np.load('/app/output/at_approach/depth_forward.npy')[-1];K=np.array(json.load(open('/app/output/spec.json'))['cameras']['forward']['intrinsic_cv']);T=np.array(json.load(open('/app/output/spec.json'))['cameras']['forward']['cam2world_gl']);
for y in [149,151,153,156,160,164,168,170,172,175]:
 for x in [177,181,185]:
  d=float(D[y,x]);v=np.linalg.inv(K)@np.array([x,y,1]);P=T@np.r_[np.array([1,-1,-1])*(d*v),1];print(x,y,round(d,3),np.round(P[:3],3))
PY

